/**
 * AI Engineer — Type Definitions
 *
 * All interfaces and types used by the AI Engineer module.
 * The AI Engineer upgrades the cognitive programs (prompts, behavioral configs)
 * of all other intelligence modules.
 */


/** What kind of cognitive program an UpgradeTarget contains. */
export type UpgradeKind = 'prompt' | 'config'

/**
 * Risk level of an upgrade.
 *
 * - low:    Cosmetic prompt rewrites; fast trial (20 turns), auto-apply on any improvement.
 * - medium: Structural prompt or config changes; longer trial (40 turns), +10% gate.
 * - high:   Core logic changes; longest trial (80 turns), +15% gate, archived for review.
 */
export type UpgradeRisk = 'low' | 'medium' | 'high'

/** Pipeline phase the AI Engineer is currently in. */
export type UpgradePhase =
  | 'idle'
  | 'selecting'
  | 'drafting'
  | 'critiquing'
  | 'trialing'
  | 'pre_conclude'
  | 'concluding'

/** Outcome of a concluded trial. */
export type TrialOutcome = 'accepted' | 'rejected' | 'inconclusive' | 'error'


/**
 * A single upgradeable cognitive program within an intelligence module.
 *
 * The catalog ships with built-in targets for every supported module.
 * Additional targets can be registered at runtime via UpgradeCatalog.register().
 */
export interface UpgradeTarget {
  /** Globally unique identifier in the form "{moduleId}/{targetId}". */
  id: string

  /** Parent intelligence module (e.g. "thinker", "dialectic"). */
  moduleId: string

  /** Human-readable name shown in admin API / Observatory. */
  name: string

  /** What this target does and why it matters to overall quality. */
  description: string

  /** What kind of value this target contains. */
  kind: UpgradeKind

  /** Risk level — controls trial length and acceptance thresholds. */
  risk: UpgradeRisk

  /**
   * KV key where the live (possibly upgraded) value is stored.
   * At startup, if this key is absent the module falls back to its default.
   */
  kvKey: string

  /**
   * EventBus event type emitted after writing a new value so the target module
   * can hot-reload without a restart.  May be undefined for targets that
   * are read from KV fresh on each use (no reload needed).
   */
  reloadEvent?: string

  /**
   * The factory default value.  Used as the baseline for critique and as the
   * revert target when no prior KV value exists.
   */
  defaultValue: string | Record<string, unknown>

  /**
   * Names of health metrics that best reflect this target's quality.
   * Used to determine whether a trial improved or degraded performance.
   * Metric names must match keys produced by PerformanceMonitor.
   */
  primaryMetrics: string[]

  /** Minimum turns between upgrade attempts on this target (cooldown). */
  cooldownTurns: number

  /** How many turns to run a trial before concluding it. */
  trialTurns: number

  /**
   * Minimum relative improvement in at least one primary metric required to
   * accept an upgrade (expressed as a fraction, e.g. 0.03 = 3 %).
   */
  acceptanceThreshold: number
}


/**
 * A draft upgrade generated by the LLM-guided evolution pipeline.
 * Proposals progress through: draft → critique gate → trial → conclusion.
 */
export interface UpgradeProposal {
  id: string
  targetId: string
  moduleId: string

  /** Wall-clock ms when this proposal was generated. */
  generatedAt: number

  /** Summary of why the current value needs improvement. */
  critique: string

  /** Specific weaknesses identified by the critique step. */
  weaknesses: string[]

  /**
   * The value that was active when the proposal was generated.
   * Used as the rollback target if the trial is rejected.
   */
  before: string | Record<string, unknown>

  /** The proposed new value. */
  after: string | Record<string, unknown>

  /** Why the rewrite should improve performance. */
  rationale: string

  /** Self-critique validation score (0–10). Proposals scoring < 7 are discarded. */
  validationScore: number

  /** Explanation accompanying the validation score. */
  validationReason: string
}


/**
 * An active or completed trial of an UpgradeProposal.
 * Only one trial can be active at a time.
 */
export interface UpgradeTrial {
  id: string
  proposalId: string
  targetId: string
  moduleId: string

  phase: 'active' | 'concluded'

  startedAt: number
  concludedAt?: number

  /** How many turns have been observed since the trial started. */
  turnsObserved: number

  /** KV key where the backup of the pre-trial value is stored. */
  backupKey: string

  /** Outcome, set when phase === 'concluded'. */
  outcome?: TrialOutcome

  /** Human-readable explanation of the outcome decision. */
  outcomeReason?: string

  /**
   * Health metric snapshot collected during the TRIAL_WINDOW turns
   * immediately before the trial started (baseline).
   */
  baselineMetrics: Record<string, number>

  /**
   * Health metric snapshot collected during the trial window.
   * Compared against baselineMetrics to determine outcome.
   */
  trialMetrics: Record<string, number>

  /**
   * Relative change per metric: (trial - baseline) / baseline.
   * Positive values mean improvement; set when phase === 'concluded'.
   */
  deltaPercent?: Record<string, number>
}


/** A single captured performance data-point for a module. */
export interface HealthSignal {
  metricName: string
  value: number
  timestamp: number
  moduleId: string
  /** EventBus event type that produced this signal. */
  eventSource: string
}

/**
 * Aggregated health summary for a single module.
 * Drives target selection in the SELECTING phase.
 */
export interface ModuleHealth {
  moduleId: string
  /** Composite health score in [0, 1].  Lower = more in need of upgrade. */
  healthScore: number
  trend: 'improving' | 'stable' | 'degrading' | 'unknown'
  signalCount: number
  lastSignalAt?: number
  lastUpgradeAttemptAt?: number
  upgradeCount: number
}


/** Versioned backup entry for upgrade history */
export interface UpgradeBackup {
  targetId: string
  kvKey: string
  value: string | Record<string, unknown>
  trialId: string
  timestamp: number
}

/** Pre-conclude recommendation from metrics evaluation */
export interface PreConcludeResult {
  trial: UpgradeTrial
  target: UpgradeTarget
  deltaPercent: Record<string, number>
  recommendation: TrialOutcome
  reason: string
}


/** Persisted snapshot of the AI Engineer's mutable state.  Stored in KV. */
export interface EngineerState {
  phase: UpgradePhase
  activeTrial?: UpgradeTrial
  activeProposal?: UpgradeProposal

  /** Map from targetId → last attempt timestamp (ms). */
  cooldowns: Record<string, number>

  /** Wall-clock ms when the last trial was concluded. */
  lastTrialConcludedAt?: number

  /** Total proposals generated (lifetime). */
  totalProposals: number

  /** Total accepted upgrades (lifetime). */
  totalAccepted: number

  /** Total rejected trials (lifetime). */
  totalRejected: number

  /** Recent concluded trials (last 20, newest first). */
  recentTrials: UpgradeTrial[]
}


/** Snapshot returned by getEngineerSummary() for the admin API and Observatory. */
export interface EngineerSummary {
  phase: UpgradePhase
  totalProposals: number
  totalAccepted: number
  totalRejected: number
  activeTrial: UpgradeTrial | null
  recentUpgrades: Array<{
    targetId: string
    moduleId: string
    concludedAt: number
    outcome: TrialOutcome
    deltaPercent: Record<string, number>
  }>
  moduleHealth: ModuleHealth[]
  /** Catalog of all registered targets with their cooldown status. */
  catalog: Array<{
    id: string
    moduleId: string
    name: string
    risk: UpgradeRisk
    onCooldown: boolean
    turnsUntilEligible: number
  }>
}
